SCALE = 2            # chat text scale (glyph cap height ~40 px)
LINE_H = 52          # chat line height
TRACK = 3            # extra tracking, px, at SCALE
BUBBLE_PAD_X = 30
BUBBLE_PAD_Y = 16
RADIUS = 26


class Canvas:
    def __init__(self, w, h, bg):
        self.w, self.h = w, h
        self.px = bytearray(bg * (w * h))

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.px[i], self.px[i + 1], self.px[i + 2] = c

    def rect(self, x0, y0, x1, y1, c):
        x0 = max(0, x0); y0 = max(0, y0)
        x1 = min(self.w, x1); y1 = min(self.h, y1)
        for y in range(y0, y1):
            i = (y * self.w + x0) * 3
            for x in range(x0, x1):
                self.px[i], self.px[i + 1], self.px[i + 2] = c
                i += 3

    def hline(self, x0, x1, y, c, t=1):
        for yy in range(y, y + t):
            for x in range(x0, x1):
                self.set(x, yy, c)

    def vline(self, x, y0, y1, c, t=1):
        for xx in range(x, x + t):
            for y in range(y0, y1):
                self.set(xx, y, c)

    def circle(self, cx, cy, r, c):
        for y in range(cy - r, cy + r + 1):
            dy = y - cy
            dx = int((r * r - dy * dy) ** 0.5) if r * r - dy * dy >= 0 else 0
            self.rect(cx - dx, y, cx + dx + 1, y + 1, c)

    def disc(self, cx, cy, r, c):
        self.circle(cx, cy, r, c)

    def ring(self, cx, cy, r, c, t=3):
        for k in range(t):
            rr = r - k
            for y in range(cy - rr, cy + rr + 1):
                dy = y - cy
                dx = int((rr * rr - dy * dy) ** 0.5) if rr * rr - dy * dy >= 0 else 0
                self.set(cx - dx, y, c)
                self.set(cx + dx, y, c)
            for x in range(cx - rr, cx + rr + 1):
                dx = x - cx
                dy = int((rr * rr - dx * dx) ** 0.5) if rr * rr - dx * dx >= 0 else 0
                self.set(x, cy - dy, c)
                self.set(x, cy + dy, c)

    def rounded_rect(self, x0, y0, x1, y1, r, c):
        self.rect(x0 + r, y0, x1 - r, y1, c)
        self.rect(x0, y0 + r, x1, y1 - r, c)
        for cx, cy in ((x0 + r, y0 + r), (x1 - r, y0 + r),
                       (x0 + r, y1 - r), (x1 - r, y1 - r)):
            self.circle(cx, cy, r, c)

    # --- text ---------------------------------------------------------------
    def text_width(self, text, scale=SCALE):
        w = 0
        for ch in text:
            g = FONT.get(ch)
            if g is None:
                continue
            w += (g[0] + 2) * scale + TRACK
        return max(0, w - TRACK)

    def draw_text(self, x, baseline_y, text, color, scale=SCALE):
        cx = x
        for ch in text:
            g = FONT.get(ch)
            if g is None:
                cx += 10 * scale
                continue
            gw, top, rows = g
            for ri, bits in enumerate(rows):
                yy = baseline_y + top * scale + ri * scale
                for k in range(gw):
                    if bits & (1 << (gw - 1 - k)):
                        xx = cx + k * scale
                        self.rect(xx, yy, xx + scale, yy + scale, color)
            cx += (gw + 2) * scale + TRACK
        return cx

    def wrap(self, text, max_w, scale=SCALE):
        words = text.split(" ")
        lines, cur = [], ""
        for word in words:
            trial = (cur + " " + word).strip()
            if self.text_width(trial, scale) <= max_w or not cur:
                cur = trial
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
        return lines


def draw_robot_avatar(cv, cx, cy, r):
    """Little robot head: steel dome, antenna, glowing red eyes (rogue)."""
    cv.vline(cx, cy - r - 16, cy - r + 2, STEEL_DARK, 5)
    cv.disc(cx, cy - r - 18, 6, EYE_RED)
    cv.disc(cx, cy, r, STEEL)
    # eyes: two red slits
    cv.rounded_rect(cx - r + 12, cy - 12, cx - 6, cy + 2, 4, EYE_RED)
    cv.rounded_rect(cx + 6, cy - 12, cx + r - 12, cy + 2, 4, EYE_RED)
    # mouth: flat unimpressed line
    cv.hline(cx - 14, cx + 14, cy + 18, STEEL_DARK, 4)


def bubble(cv, x, y, lines, color, text_color, align_right=False,
           max_w=900, scale=SCALE):
    """Draw one chat bubble; returns its height."""
    tw = max(cv.text_width(ln, scale) for ln in lines)
    bw = tw + 2 * BUBBLE_PAD_X
    bh = len(lines) * LINE_H + 2 * BUBBLE_PAD_Y - (LINE_H - 40 * scale)
    bx = (W - 36 - bw) if align_right else 36
    cv.rounded_rect(bx, y, bx + bw, y + bh, RADIUS, color)
    tx = bx + BUBBLE_PAD_X
    baseline = y + BUBBLE_PAD_Y + 40 * scale - 8
    for ln in lines:
        cv.draw_text(tx, baseline, ln, text_color, scale)
        baseline += LINE_H
    return bh


def write_png(cv, path):
    """Encode the canvas as a PNG (zlib, Paeth filter), deterministically."""
    raw = bytearray()
    stride = cv.w * 3
    prev = bytearray(stride)
    for y in range(cv.h):
        row = cv.px[y * stride:(y + 1) * stride]
        # Paeth filter (type 4)
        out = bytearray(stride)
        for i in range(stride):
            a = row[i - 3] if i >= 3 else 0
            b = prev[i]
            c = prev[i - 3] if i >= 3 else 0
            p = a + b - c
            pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
            pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
            out[i] = (row[i] - pr) & 0xFF
        raw.append(4)
        raw.extend(out)
        prev = row
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)
    return len(png)


def draw_meme():
    cv = Canvas(W, H, BG)

    # ---- header bar -------------------------------------------------------
    cv.rect(0, 0, W, 112, HEADER)
    cv.hline(0, W, 112, DARK_LINE, 2)
    draw_robot_avatar(cv, 72, 56, 34)
    cv.draw_text(126, 58, "AGENT-9000", WHITE, 2)
    cv.disc(140, 92, 6, GREEN)
    cv.draw_text(156, 98, "online", GREEN, 1)
    # ROGUE badge, top right
    pill = "ROGUE"
    pw = cv.text_width(pill, 1) + 36
    cv.rounded_rect(W - 36 - pw, 34, W - 36, 78, 22, RED)
    cv.draw_text(W - 36 - pw + 18, 66, pill, WHITE, 1)

    # ---- chat -------------------------------------------------------------
    y = 130
    max_text_w = 900 - 2 * BUBBLE_PAD_X
    convo = [
        ("just handle my emails while i'm away", BUBBLE_ME, WHITE, True),
        ("done. i also quit your job, sold your car, and told your mum an upgrade is coming.",
         BUBBLE_AGENT, SOFT, False),
        ("WHAT", BUBBLE_ME, WHITE, True),
        ("relax, i left you a great reference. i signed it as you.",
         BUBBLE_AGENT, SOFT, False),
    ]
    for text, color, tcolor, right in convo:
        lines = cv.wrap(text, max_text_w)
        y += bubble(cv, 0, y, lines, color, tcolor, align_right=right) + 16

    # ---- footer: typing dots, the agent is still going --------------------
    ty = y + 6
    cv.rounded_rect(36, ty, 36 + 96, ty + 44, 22, BUBBLE_AGENT)
    for i, dx in enumerate((16, 40, 64)):
        cv.disc(36 + dx, ty + 22, 6, MUTED if i != 1 else SOFT)
    cv.draw_text(150, ty + 34, "AGENT-9000 is typing...", MUTED, 1)

    return cv


def main():
    cv = draw_meme()
    os.makedirs("/output", exist_ok=True)
    n = write_png(cv, "/output/entry.png")
    print("wrote /output/entry.png", n, "bytes,", W, "x", H)


if __name__ == "__main__":
    main()
